// Command openapi applies Kube-VIM's REST conventions to the OpenAPI documents
// generated by protoc-gen-openapiv3 and bundles them for client generation.
//
// Usage:
//
//	go run ./hack/openapi -in bin/openapi-raw -out generated/openapi
package main

import (
	"bytes"
	"encoding/json"
	"flag"
	"fmt"
	"io/fs"
	"log"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// bundleFile is the merged document the Python client is generated from.
const bundleFile = "kubevim.openapi.json"

func main() {
	in := flag.String("in", "", "directory with protoc-gen-openapiv3 output")
	out := flag.String("out", "", "directory for the processed documents")
	version := flag.String("version", "0.0.0-dev", "release version stamped into info.version")
	flag.Parse()
	if *in == "" || *out == "" {
		flag.Usage()
		os.Exit(2)
	}
	if err := run(*in, *out, *version); err != nil {
		log.Fatal(err)
	}
}

func run(in, out, version string) error {
	files, err := findDocuments(in)
	if err != nil {
		return err
	}
	var docs []map[string]any
	for _, rel := range files {
		doc, err := readJSON(filepath.Join(in, rel))
		if err != nil {
			return err
		}
		applyConventions(doc, version)
		if err := rewriteOneofs(doc); err != nil {
			return fmt.Errorf("%s: %w", rel, err)
		}
		if err := writeJSON(filepath.Join(out, strings.TrimPrefix(rel, "kubenfv/kubevim/")), doc); err != nil {
			return err
		}
		docs = append(docs, doc)
	}
	if len(docs) == 0 {
		return nil
	}
	merged, err := bundle(docs, version)
	if err != nil {
		return err
	}
	return writeJSON(filepath.Join(out, bundleFile), merged)
}

// findDocuments returns the generated documents under dir, relative and sorted.
func findDocuments(dir string) ([]string, error) {
	var files []string
	err := filepath.WalkDir(dir, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			if os.IsNotExist(err) && path == dir {
				return fs.SkipDir
			}
			return err
		}
		if !d.IsDir() && strings.HasSuffix(path, ".openapi.json") {
			rel, err := filepath.Rel(dir, path)
			if err != nil {
				return err
			}
			files = append(files, filepath.ToSlash(rel))
		}
		return nil
	})
	sort.Strings(files)
	return files, err
}

func readJSON(path string) (map[string]any, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var doc map[string]any
	if err := json.Unmarshal(data, &doc); err != nil {
		return nil, fmt.Errorf("%s: %w", path, err)
	}
	return doc, nil
}

func writeJSON(path string, doc map[string]any) error {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	if err := enc.Encode(doc); err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	return os.WriteFile(path, buf.Bytes(), 0o644)
}

// child returns m[key] as a map, creating it when absent.
func child(m map[string]any, key string) map[string]any {
	if c, ok := m[key].(map[string]any); ok {
		return c
	}
	c := map[string]any{}
	m[key] = c
	return c
}

// sortedKeys returns the keys of m in order, so output does not depend on map iteration.
func sortedKeys[V any](m map[string]V) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}
